#!/bin/bash\n\n# EZBI Analytics Deployment Script\n# This script handles deployment to different environments\n\nset -euo pipefail\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Default values\nENVIRONMENT=\"development\"\nNAMESPACE=\"ezbi-analytics\"\nDRY_RUN=false\nVERBOSE=false\nSKIP_TESTS=false\nSKIP_BACKUP=false\nFORCE_REBUILD=false\n\n# Function to print colored output\nprint_status() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nprint_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nprint_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nprint_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\n# Function to show usage\nshow_usage() {\n    cat << EOF\nUsage: $0 [OPTIONS] <environment>\n\nEnvironments:\n  development    Deploy to development environment\n  staging        Deploy to staging environment\n  production     Deploy to production environment\n\nOptions:\n  -n, --namespace NAMESPACE    Kubernetes namespace (default: ezbi-analytics)\n  -d, --dry-run               Show what would be deployed without actually deploying\n  -v, --verbose               Enable verbose output\n  -t, --skip-tests            Skip running tests before deployment\n  -b, --skip-backup           Skip backup creation (not recommended for production)\n  -f, --force-rebuild         Force rebuild of all images\n  -h, --help                  Show this help message\n\nExamples:\n  $0 development\n  $0 staging --dry-run\n  $0 production --skip-tests --verbose\n\nEOF\n}\n\n# Function to check prerequisites\ncheck_prerequisites() {\n    print_status \"Checking prerequisites...\"\n    \n    # Check if kubectl is installed\n    if ! command -v kubectl &> /dev/null; then\n        print_error \"kubectl is not installed. Please install kubectl first.\"\n        exit 1\n    fi\n    \n    # Check if docker is installed\n    if ! command -v docker &> /dev/null; then\n        print_error \"Docker is not installed. Please install Docker first.\"\n        exit 1\n    fi\n    \n    # Check if helm is installed (if using Helm charts)\n    if ! command -v helm &> /dev/null; then\n        print_warning \"Helm is not installed. Some features may not work.\"\n    fi\n    \n    # Check kubectl connection\n    if ! kubectl cluster-info &> /dev/null; then\n        print_error \"Cannot connect to Kubernetes cluster. Please check your kubeconfig.\"\n        exit 1\n    fi\n    \n    print_success \"Prerequisites check passed\"\n}\n\n# Function to set environment variables\nset_environment() {\n    local env=$1\n    print_status \"Setting up environment: $env\"\n    \n    # Source environment file\n    if [[ -f \"./environments/.env.$env\" ]]; then\n        set -a\n        source \"./environments/.env.$env\"\n        set +a\n        print_success \"Environment variables loaded from .env.$env\"\n    else\n        print_error \"Environment file .env.$env not found\"\n        exit 1\n    fi\n    \n    # Set image tags based on environment\n    case $env in\n        development)\n            IMAGE_TAG=\"latest\"\n            ;;\n        staging)\n            IMAGE_TAG=\"develop\"\n            ;;\n        production)\n            IMAGE_TAG=\"main\"\n            ;;\n        *)\n            print_error \"Unknown environment: $env\"\n            exit 1\n            ;;\n    esac\n    \n    export IMAGE_TAG\n    print_status \"Using image tag: $IMAGE_TAG\"\n}\n\n# Function to run tests\nrun_tests() {\n    if [[ \"$SKIP_TESTS\" == \"true\" ]]; then\n        print_warning \"Skipping tests as requested\"\n        return 0\n    fi\n    \n    print_status \"Running tests...\"\n    \n    # Run backend tests\n    print_status \"Running backend tests...\"\n    cd ../backend\n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        python -m pytest -v\n    else\n        python -m pytest\n    fi\n    cd ../deployment\n    \n    # Run frontend tests\n    print_status \"Running frontend tests...\"\n    cd ../frontend\n    npm test -- --watchAll=false\n    cd ../deployment\n    \n    # Run ML engine tests\n    print_status \"Running ML engine tests...\"\n    cd ../ml-engine\n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        python -m pytest -v\n    else\n        python -m pytest\n    fi\n    cd ../deployment\n    \n    print_success \"All tests passed\"\n}\n\n# Function to build Docker images\nbuild_images() {\n    print_status \"Building Docker images...\"\n    \n    local components=(\"backend\" \"frontend\" \"ml-engine\")\n    \n    for component in \"${components[@]}\"; do\n        print_status \"Building $component image...\"\n        \n        if [[ \"$FORCE_REBUILD\" == \"true\" ]]; then\n            docker build --no-cache -t \"ezbi/$component:$IMAGE_TAG\" \"../$component\"\n        else\n            docker build -t \"ezbi/$component:$IMAGE_TAG\" \"../$component\"\n        fi\n        \n        if [[ \"$VERBOSE\" == \"true\" ]]; then\n            docker images \"ezbi/$component:$IMAGE_TAG\"\n        fi\n    done\n    \n    print_success \"All images built successfully\"\n}\n\n# Function to create backup\ncreate_backup() {\n    if [[ \"$SKIP_BACKUP\" == \"true\" ]]; then\n        print_warning \"Skipping backup as requested\"\n        return 0\n    fi\n    \n    if [[ \"$ENVIRONMENT\" == \"development\" ]]; then\n        print_status \"Skipping backup for development environment\"\n        return 0\n    fi\n    \n    print_status \"Creating backup...\"\n    \n    # Create timestamp for backup\n    local timestamp=$(date +\"%Y%m%d_%H%M%S\")\n    local backup_name=\"ezbi_backup_${ENVIRONMENT}_${timestamp}\"\n    \n    # Database backup\n    print_status \"Creating database backup...\"\n    kubectl exec -n \"$NAMESPACE\" deployment/postgres-deployment -- pg_dump -U ezbi_user ezbi_analytics > \"backups/${backup_name}_db.sql\"\n    \n    # Redis backup\n    print_status \"Creating Redis backup...\"\n    kubectl exec -n \"$NAMESPACE\" deployment/redis-deployment -- redis-cli BGSAVE\n    \n    # Create backup directory if it doesn't exist\n    mkdir -p backups\n    \n    print_success \"Backup created: $backup_name\"\n}\n\n# Function to deploy to Kubernetes\ndeploy_to_kubernetes() {\n    print_status \"Deploying to Kubernetes...\"\n    \n    # Create namespace if it doesn't exist\n    if ! kubectl get namespace \"$NAMESPACE\" &> /dev/null; then\n        print_status \"Creating namespace: $NAMESPACE\"\n        if [[ \"$DRY_RUN\" == \"false\" ]]; then\n            kubectl create namespace \"$NAMESPACE\"\n        fi\n    fi\n    \n    # Apply manifests in order\n    local manifests=(\n        \"kubernetes/namespace.yaml\"\n        \"kubernetes/secrets.yaml\"\n        \"kubernetes/storage.yaml\"\n        \"kubernetes/database.yaml\"\n        \"kubernetes/backend.yaml\"\n        \"kubernetes/frontend.yaml\"\n        \"kubernetes/ml-engine.yaml\"\n        \"kubernetes/monitoring.yaml\"\n        \"kubernetes/ingress.yaml\"\n    )\n    \n    for manifest in \"${manifests[@]}\"; do\n        if [[ -f \"$manifest\" ]]; then\n            print_status \"Applying $manifest...\"\n            \n            # Replace image tags in manifests\n            local temp_manifest=\"/tmp/$(basename $manifest)\"\n            sed \"s|image: ezbi/|image: ezbi/|g; s|:latest|:$IMAGE_TAG|g\" \"$manifest\" > \"$temp_manifest\"\n            \n            if [[ \"$DRY_RUN\" == \"true\" ]]; then\n                echo \"Would apply: $manifest\"\n                if [[ \"$VERBOSE\" == \"true\" ]]; then\n                    kubectl apply -f \"$temp_manifest\" --dry-run=client\n                fi\n            else\n                kubectl apply -f \"$temp_manifest\"\n            fi\n            \n            rm -f \"$temp_manifest\"\n        else\n            print_warning \"Manifest file not found: $manifest\"\n        fi\n    done\n    \n    print_success \"Kubernetes deployment completed\"\n}\n\n# Function to wait for deployment\nwait_for_deployment() {\n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        print_status \"Skipping deployment wait (dry run mode)\"\n        return 0\n    fi\n    \n    print_status \"Waiting for deployment to complete...\"\n    \n    local deployments=(\n        \"postgres-deployment\"\n        \"redis-deployment\"\n        \"backend-deployment\"\n        \"frontend-deployment\"\n        \"ml-engine-deployment\"\n    )\n    \n    for deployment in \"${deployments[@]}\"; do\n        print_status \"Waiting for $deployment...\"\n        kubectl rollout status deployment/\"$deployment\" -n \"$NAMESPACE\" --timeout=300s\n    done\n    \n    print_success \"All deployments are ready\"\n}\n\n# Function to run health checks\nrun_health_checks() {\n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        print_status \"Skipping health checks (dry run mode)\"\n        return 0\n    fi\n    \n    print_status \"Running health checks...\"\n    \n    # Wait a bit for services to be ready\n    sleep 30\n    \n    # Check backend health\n    print_status \"Checking backend health...\"\n    if kubectl exec -n \"$NAMESPACE\" deployment/backend-deployment -- curl -f http://localhost:8000/health; then\n        print_success \"Backend health check passed\"\n    else\n        print_error \"Backend health check failed\"\n        return 1\n    fi\n    \n    # Check ML engine health\n    print_status \"Checking ML engine health...\"\n    if kubectl exec -n \"$NAMESPACE\" deployment/ml-engine-deployment -- curl -f http://localhost:8001/health; then\n        print_success \"ML engine health check passed\"\n    else\n        print_error \"ML engine health check failed\"\n        return 1\n    fi\n    \n    # Check frontend health\n    print_status \"Checking frontend health...\"\n    if kubectl exec -n \"$NAMESPACE\" deployment/frontend-deployment -- curl -f http://localhost:3000/api/health; then\n        print_success \"Frontend health check passed\"\n    else\n        print_error \"Frontend health check failed\"\n        return 1\n    fi\n    \n    print_success \"All health checks passed\"\n}\n\n# Function to show deployment status\nshow_deployment_status() {\n    print_status \"Deployment Status:\"\n    \n    echo \"\\n=== PODS ===\"\n    kubectl get pods -n \"$NAMESPACE\" -o wide\n    \n    echo \"\\n=== SERVICES ===\"\n    kubectl get services -n \"$NAMESPACE\"\n    \n    echo \"\\n=== INGRESS ===\"\n    kubectl get ingress -n \"$NAMESPACE\"\n    \n    echo \"\\n=== PERSISTENT VOLUMES ===\"\n    kubectl get pv | grep \"$NAMESPACE\"\n    \n    echo \"\\n=== RESOURCE USAGE ===\"\n    kubectl top pods -n \"$NAMESPACE\" 2>/dev/null || echo \"Metrics server not available\"\n}\n\n# Function to cleanup on exit\ncleanup() {\n    print_status \"Cleaning up...\"\n    # Remove any temporary files\n    rm -f /tmp/*.yaml\n}\n\n# Main deployment function\nmain() {\n    # Parse command line arguments\n    while [[ $# -gt 0 ]]; do\n        case $1 in\n            -n|--namespace)\n                NAMESPACE=\"$2\"\n                shift 2\n                ;;\n            -d|--dry-run)\n                DRY_RUN=true\n                shift\n                ;;\n            -v|--verbose)\n                VERBOSE=true\n                shift\n                ;;\n            -t|--skip-tests)\n                SKIP_TESTS=true\n                shift\n                ;;\n            -b|--skip-backup)\n                SKIP_BACKUP=true\n                shift\n                ;;\n            -f|--force-rebuild)\n                FORCE_REBUILD=true\n                shift\n                ;;\n            -h|--help)\n                show_usage\n                exit 0\n                ;;\n            -*)\n                print_error \"Unknown option: $1\"\n                show_usage\n                exit 1\n                ;;\n            *)\n                ENVIRONMENT=\"$1\"\n                shift\n                ;;\n        esac\n    done\n    \n    # Validate environment\n    if [[ ! \"$ENVIRONMENT\" =~ ^(development|staging|production)$ ]]; then\n        print_error \"Invalid environment: $ENVIRONMENT\"\n        show_usage\n        exit 1\n    fi\n    \n    # Set up trap for cleanup\n    trap cleanup EXIT\n    \n    print_status \"Starting deployment to $ENVIRONMENT environment...\"\n    \n    # Run deployment steps\n    check_prerequisites\n    set_environment \"$ENVIRONMENT\"\n    run_tests\n    build_images\n    create_backup\n    deploy_to_kubernetes\n    wait_for_deployment\n    run_health_checks\n    \n    print_success \"Deployment completed successfully!\"\n    \n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        show_deployment_status\n    fi\n    \n    # Show access information\n    case $ENVIRONMENT in\n        development)\n            print_status \"Access your application at: http://localhost:3000\"\n            ;;\n        staging)\n            print_status \"Access your application at: https://staging.ezbi.example.com\"\n            ;;\n        production)\n            print_status \"Access your application at: https://ezbi.example.com\"\n            ;;\n    esac\n}\n\n# Run main function\nmain \"$@\""